import{_ as e,o as t,c as o,a0 as n}from"./chunks/framework.DQOulFGV.js";const h=JSON.parse('{"title":"Donation funds transparency (May 2026)","description":"","frontmatter":{"title":"Donation funds transparency (May 2026)","date":"2026-06-02T00:00:00.000Z","category":"News","tags":["minecraft","modding","updates"]},"headers":[],"relativePath":"posts/2026-06-02-donation-funds-transparency-may.md","filePath":"posts/2026-06-02-donation-funds-transparency-may.md"}'),s={name:"posts/2026-06-02-donation-funds-transparency-may.md"};function r(i,a,l,d,p,c){return t(),o("div",null,[...a[0]||(a[0]=[n('<p><img src="https://cdn.modrinth.com/data/9rlXSyLg/images/491c87c96cd602ec45774ce0b0cb9fe4d25ba074.png" alt="Saving for a Laptop Progress"></p><p>In May, I&#39;ve received a total of six donations and kind messages from very generous players around the world, I couldn&#39;t be more thankful of this amazing community that supports mod development this much.</p><p>I&#39;d like to thank all players for being in this journey with me, I would have never imagined two years ago right now I would be creating mods for Minecraft and reach so many players from different countries.</p><p>This will be incredibly useful for when I&#39;m not home for a few days or weeks because I&#39;m busy with university, and unfortunately I just can&#39;t carry my whole PC with me.</p><h2 id="list-of-donations" tabindex="-1">List of donations: <a class="header-anchor" href="#list-of-donations" aria-label="Permalink to &quot;List of donations:&quot;">​</a></h2><p>Values are expressed in United States Dollar (USD).</p><ul><li>Chro donated $5.00 on May 2, 2026.</li><li>Melchior donated $6.00 on May 5, 2026.</li><li>Jonathan donated $30.00 on May 15, 2026.</li><li>Cassandra donated $100.00 on May 23, 2026.</li><li>WolfCraft donated $27.80 on May 29, 2026.</li><li>Lucy donated $5.00 on May 31, 2026.</li></ul><h2 id="paypal-fees" tabindex="-1">PayPal Fees: <a class="header-anchor" href="#paypal-fees" aria-label="Permalink to &quot;PayPal Fees:&quot;">​</a></h2><ul><li>Total fees for all six donations: $11.25.</li></ul><h2 id="total" tabindex="-1">Total: <a class="header-anchor" href="#total" aria-label="Permalink to &quot;Total:&quot;">​</a></h2><ul><li>The total received amount after fees is: $163.79.</li></ul><p>All donations are incredibly appreciated and every amount counts, please send a message with your donation because I love to read those.</p><p><a href="https://paypal.me/kevgelhorn" target="_blank" rel="noreferrer"><img src="https://raw.githubusercontent.com/intergrav/devins-badges/refs/heads/v3/assets/cozy/donate/paypal-singular_64h.png" alt="Donate Button"></a></p>',13)])])}const f=e(s,[["render",r]]);export{h as __pageData,f as default};
